SELECT products.supplier_id, CASE WHEN YEAR(products.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(products.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END AS launch_cohort, SUM(inventory.quantity) AS total_quantity, MAX(inventory.quantity) - MIN(inventory.quantity) AS quantity_range FROM inventory LEFT JOIN stores ON inventory.store_id = stores.id LEFT JOIN products ON inventory.product_id = products.id GROUP BY products.supplier_id, CASE WHEN YEAR(products.launch_date) < 2024 THEN 'before_2024' WHEN YEAR(products.launch_date) = 2024 THEN '2024' ELSE 'after_2024' END ORDER BY total_quantity DESC, supplier_id, launch_cohort LIMIT 5;
